//go:build !purego

package sha3

// keccakF1600C906 is the CRYPTOGAMS no-Zbb round with one-instruction rotates
// (keccak_c906_riscv64.s, generated by gen_keccak_c906.py). NanoKVM OS runs
// only on the T-Head C906, which has XTheadBb: there is no selection.
//
//go:noescape
func keccakF1600C906(a *[200]byte)

func keccakF1600(a *[200]byte) {
	keccakF1600C906(a)
}

func (d *Digest) write(p []byte) (n int, err error) {
	return d.writeGeneric(p)
}
func (d *Digest) read(out []byte) (n int, err error) {
	return d.readGeneric(out)
}
func (d *Digest) sum(b []byte) []byte {
	return d.sumGeneric(b)
}
